<script setup lang="ts">import { computed } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; const auth=useAuthStore(),router=useRouter();const menus=computed(()=>auth.session?.menus??[]);async function logout(){await auth.logout();}</script><template><el-container class="shell"><el-aside width="240px"><h2>医院平台</h2><el-menu :router="true" :default-active="router.currentRoute.value.path"><el-menu-item index="/"><span>工作台</span></el-menu-item><el-menu-item v-for="menu in menus.filter(m=>m.route_path!=='/')" :key="String(menu.id)" :index="menu.route_path"><span>{{menu.menu_name}}</span></el-menu-item></el-menu></el-aside><el-container><el-header><span>基础管理</span><div><span>{{auth.session?.username}}</span><el-button text @click="logout">退出登录</el-button></div></el-header><el-main><router-view/></el-main></el-container></el-container></template>
